'use strict';
(()=>{
 const $=id=>document.getElementById(id),ar=document.documentElement.lang==='ar',L=(a,b)=>ar?b:a,slug=document.body.dataset.tool;
 if(!$('pdf-files'))return;
 const input=$('pdf-files'),run=$('pdf-run'),zone=$('pdf-drop');let busy=false,files=[],doc=null,token=0,wordReady=false;
 const status=(s,error=false)=>{$('status').textContent=s;$('status').classList.toggle('error',error)};
 const save=(bytes,name)=>{const blob=new Blob([bytes],{type:'application/pdf'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)};
 const setBusy=b=>{busy=b;input.disabled=b;run.disabled=b||(slug==='word-to-pdf'?!wordReady:slug==='images-to-pdf'?!files.length:!doc);document.querySelectorAll('#pdf-file-list button,#pdf-options input,#pdf-options select').forEach(x=>x.disabled=b);if(!b&&slug==='images-to-pdf')renderFiles()};
 function pageRange(value,count,all=false){if(!value.trim()){if(all)return Array.from({length:count},(_,i)=>i);throw Error(L('Enter at least one page number.','أدخل رقم صفحة واحدة على الأقل.'))}const result=[],seen=new Set();for(const part of value.replace(/[٠-٩]/g,c=>String('٠١٢٣٤٥٦٧٨٩'.indexOf(c))).split(/[,،]/)){let m=part.trim().match(/^(\d+)(?:\s*-\s*(\d+))?$/);if(!m)throw Error(L('Invalid page range. Use 1, 3-5.','نطاق غير صالح. استخدم 1, 3-5.'));const first=Number(m[1]),last=Number(m[2]||m[1]);if(first<1||last>count||first>last)throw Error(L(`Use page numbers from 1 to ${count}, with ascending ranges.`,`استخدم أرقاماً من 1 إلى ${count} بنطاقات تصاعدية.`));for(let n=first;n<=last;n++)if(!seen.has(n)){result.push(n-1);seen.add(n)}}return result}
 function renderFiles(){const list=$('pdf-file-list');if(!list)return;list.replaceChildren();files.forEach((file,index)=>{const li=document.createElement('li'),name=document.createElement('span');name.className='file-name';name.textContent=`${index+1}. ${file.name}`;li.append(name);for(const [text,label,delta] of [['↑',L('Move up','تحريك لأعلى'),-1],['↓',L('Move down','تحريك لأسفل'),1],['×',L('Remove','إزالة'),0]]){const button=document.createElement('button');button.textContent=text;button.setAttribute('aria-label',`${label}: ${file.name}`);button.disabled=busy||(delta===-1&&index===0)||(delta===1&&index===files.length-1);button.onclick=()=>{if(delta)[files[index],files[index+delta]]=[files[index+delta],files[index]];else files.splice(index,1);renderFiles();run.disabled=!files.length};li.append(button)}list.append(li)});run.disabled=busy||!files.length}
 function pdfError(){return Error(L('Cannot read this PDF. Password-protected or damaged files are not supported.','تعذر قراءة PDF. الملفات المحمية أو التالفة غير مدعومة.'))}
 async function choose(incoming){if(busy)return;const picked=[...incoming];input.value='';if(!picked.length)return;const version=++token;status('');
 if(slug==='images-to-pdf'){
 try{if(files.length+picked.length>20||[...files,...picked].reduce((s,f)=>s+f.size,0)>50*1048576)throw Error(L('Choose up to 20 images and 50 MB total.','اختر حتى 20 صورة وبإجمالي 50 ميغابايت.'));for(const f of picked){if(f.size>20*1048576)throw Error(L('Each image must be under 20 MB.','يجب أن يكون حجم كل صورة أقل من 20 ميغابايت.'));await imageType(f)}if(version!==token)return;files.push(...picked);renderFiles();status(L(`${files.length} images ready.`,`${files.length} صور جاهزة.`))}catch(e){status(e.message,true)}input.value='';return}
 if(slug==='word-to-pdf'){
 wordReady=false;run.disabled=true;$('word-preview').hidden=true;
 try{const f=picked[0];if(!/\.docx$/i.test(f.name)||f.size>15*1048576)throw Error(L('Choose a .docx file under 15 MB. Old .doc files are not supported.','اختر ملف .docx أصغر من 15 ميغابايت. ملفات .doc القديمة غير مدعومة.'));let h=new Uint8Array(await f.slice(0,4).arrayBuffer());if(h[0]!==80||h[1]!==75)throw Error(L('This is not a valid DOCX file.','هذا ليس ملف DOCX صالحاً.'));files=[f];status(L('Preparing the local document preview…','جارٍ تجهيز معاينة المستند محلياً…'));await readyFrame;if(version!==token)return;setBusy(true);const bytes=await f.arrayBuffer();$('word-preview').contentWindow.postMessage({kind:'load',bytes,ar,token:version},'*',[bytes]);}catch(e){status(e.message,true);setBusy(false)}return}
 doc=null;run.disabled=true;$('pdf-options').hidden=true;$('pdf-details').textContent='';
 try{const f=picked[0];if(f.size>50*1048576)throw Error(L('Choose a PDF under 50 MB.','اختر PDF أصغر من 50 ميغابايت.'));const bytes=await f.arrayBuffer();if(!new TextDecoder().decode(bytes.slice(0,1024)).includes('%PDF-'))throw pdfError();let parsed;try{parsed=await PDFLib.PDFDocument.load(bytes)}catch{throw pdfError()}if(parsed.getPageCount()<1||parsed.getPageCount()>1000)throw Error(L('Choose a PDF with 1 to 1,000 pages.','اختر PDF يحتوي على 1 إلى 1,000 صفحة.'));if(version!==token)return;doc=parsed;files=[f];$('pdf-details').textContent=L(`${f.name} · ${doc.getPageCount()} pages`,`${f.name} · ${doc.getPageCount()} صفحة`);$('pdf-options').hidden=false;$('pdf-pages').value='';run.disabled=false;}catch(e){status(e.message,true)}}
 async function imageType(file){const h=new Uint8Array(await file.slice(0,12).arrayBuffer()),s=(a,b)=>String.fromCharCode(...h.slice(a,b));if(h[0]===255&&h[1]===216&&h[2]===255)return 'jpeg';if(h[0]===137&&s(1,4)==='PNG')return 'png';if(s(0,4)==='RIFF'&&s(8,12)==='WEBP')return 'webp';throw Error(L('Only JPEG, PNG and WebP images are supported.','تُدعم صور JPEG وPNG وWebP فقط.'))}
 input.onchange=e=>choose(e.target.files);for(const name of ['dragenter','dragover'])zone.addEventListener(name,e=>{e.preventDefault();zone.classList.add('dragging')});for(const name of ['dragleave','drop'])zone.addEventListener(name,e=>{e.preventDefault();zone.classList.remove('dragging')});zone.addEventListener('drop',e=>choose(e.dataTransfer.files));
 let readyFrame=Promise.resolve();
 if(slug==='word-to-pdf'){
 readyFrame=new Promise(resolve=>{const frame=$('word-preview');window.addEventListener('message',event=>{if(event.source!==frame.contentWindow)return;const data=event.data;if(data.kind==='ready'){resolve();return}if(data.token!==token)return;if(data.kind==='loaded'){wordReady=true;frame.hidden=false;status(L(`Preview ready: ${data.pages} pages. Review before downloading.`,`المعاينة جاهزة: ${data.pages} صفحة. راجعها قبل التحميل.`));setBusy(false)}if(data.kind==='error'){wordReady=false;frame.hidden=true;setBusy(false);status(data.message,true)}if(data.kind==='progress')status(L(`Creating PDF: page ${data.page} of ${data.pages}…`,`جارٍ إنشاء PDF: الصفحة ${data.page} من ${data.pages}…`));if(data.kind==='pdf'){save(data.bytes,'toolora-document.pdf');status(L('Your PDF is ready.','ملف PDF جاهز.'));setBusy(false)}});frame.addEventListener('load',()=>frame.contentWindow.postMessage({kind:'ping'},'*'));frame.contentWindow.postMessage({kind:'ping'},'*')});
 }
 run.onclick=async()=>{if(busy)return;setBusy(true);status(L('Creating your PDF on this device…','جارٍ إنشاء PDF على جهازك…'));try{
 if(slug==='word-to-pdf'){$('word-preview').contentWindow.postMessage({kind:'export',token},'*');return}
 if(slug==='images-to-pdf'){
 const out=await PDFLib.PDFDocument.create();for(let i=0;i<files.length;i++){status(L(`Adding image ${i+1} of ${files.length}…`,`جارٍ إضافة الصورة ${i+1} من ${files.length}…`));await imageType(files[i]);const bitmap=await createImageBitmap(files[i]);try{const w=bitmap.width,h=bitmap.height;if(w*h>25000000||w>10000||h>10000)throw Error(L('An image exceeds 25 megapixels or 10,000 pixels per side.','تتجاوز إحدى الصور 25 مليون بكسل أو 10,000 بكسل لكل ضلع.'));const canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;const ctx=canvas.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,w,h);ctx.drawImage(bitmap,0,0);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.92));canvas.width=canvas.height=0;if(!blob)throw Error(L('Could not encode the image.','تعذر إنشاء الصورة.'));const image=await out.embedJpg(await blob.arrayBuffer());const paper=$('pdf-paper').value;let pw=paper==='letter'?612:595.28,ph=paper==='letter'?792:841.89;if($('pdf-orientation').value==='landscape')[pw,ph]=[ph,pw];if(paper==='image'){pw=w*.75;ph=h*.75}const margin=paper==='image'?0:24,scale=Math.min((pw-2*margin)/w,(ph-2*margin)/h);out.addPage([pw,ph]).drawImage(image,{x:(pw-w*scale)/2,y:(ph-h*scale)/2,width:w*scale,height:h*scale})}finally{bitmap.close()}}
 save(await out.save(),'toolora-images.pdf');status(L('Your PDF is ready.','ملف PDF جاهز.'));return}
 const selected=pageRange($('pdf-pages').value,doc.getPageCount(),slug==='pdf-rotate');const out=await PDFLib.PDFDocument.create();let indices=selected;if(slug==='pdf-remove-pages'){const removed=new Set(selected);indices=doc.getPageIndices().filter(i=>!removed.has(i));if(!indices.length)throw Error(L('Keep at least one page in your PDF.','احتفظ بصفحة واحدة على الأقل.'))}if(slug==='pdf-rotate')indices=doc.getPageIndices();const pages=await out.copyPages(doc,indices);const rotate=new Set(selected);pages.forEach((p,i)=>{if(slug==='pdf-rotate'&&rotate.has(i))p.setRotation(PDFLib.degrees((p.getRotation().angle+Number($('pdf-angle').value))%360));out.addPage(p)});save(await out.save(),slug==='pdf-splitter'?'toolora-extracted.pdf':slug==='pdf-remove-pages'?'toolora-edited.pdf':'toolora-rotated.pdf');status(L(`Your PDF is ready: ${out.getPageCount()} pages.`,`ملف PDF جاهز: ${out.getPageCount()} صفحة.`));
 }catch(e){status(e.name==='InvalidStateError'?L('An image could not be decoded.','تعذر قراءة إحدى الصور.'):e.message,true)}finally{if(slug!=='word-to-pdf')setBusy(false)}};
})();
